 * MechRing Controller Trigger Map
 * Maps button combinations to MechMind actions
 * 
 * Button naming convention:
 *   R_ prefix = DriveRing (RIGHT joystick)
 *   L_ prefix = DomeRing (LEFT joystick)
 * 
 * Button identifiers (v2.0 protocol):
 *   BTNA-D  = Push buttons A-D (bits 0-3)
 *   TRIG    = Trigger button (bit 8)
 *   JOY     = Joystick press button (bit 9)
 *   MODE    = Mode button (bit 10)
 */

// ===== DriveRing (RIGHT joystick) - Single Buttons =====
triggerMap["R_TRIG"]    = "VolumeUp";
triggerMap["R_BTNA"]    = "Happy";
triggerMap["R_BTNB"]    = "Sad";
triggerMap["R_BTNC"]    = "DomePAllToggle";
triggerMap["R_BTND"]    = "BodyPAllToggle";
triggerMap["R_JOY"]     = "StickToggle";
triggerMap["R_MODE"]    = "QuietMode";

// ===== DomeRing (LEFT joystick) - Single Buttons =====
triggerMap["L_TRIG"]    = "VolumeDown";
triggerMap["L_BTNA"]    = "Scream";
triggerMap["L_BTNB"]    = "Wave";
triggerMap["L_BTNC"]    = "HoloLightsTogl";
triggerMap["L_BTND"]    = "MusingsToggle";
triggerMap["L_JOY"]     = "DomeAutoToggle";
triggerMap["L_MODE"]    = "FullAwake";

// ===== DriveRing (RIGHT) - Combinations =====
triggerMap["R_TRIG+R_BTNA"] = "CantinaDance";
triggerMap["R_TRIG+R_BTNB"] = "Disco";
triggerMap["R_TRIG+R_BTNC"] = "LeiaShortMsg";
triggerMap["R_TRIG+R_BTND"] = "BeepCantina";

// ===== DomeRing (LEFT) - Combinations =====
triggerMap["L_TRIG+L_BTNA"] = "ShortCircuit";
triggerMap["L_TRIG+L_BTNB"] = "Wave2";
triggerMap["L_TRIG+L_BTNC"] = "MarchingAnts";
triggerMap["L_TRIG+L_BTND"] = "WolfWhistle";

// ===== Both Rings - Combinations =====
triggerMap["R_TRIG+L_TRIG"]     = "LeiaFullMsg";
triggerMap["R_BTNA+L_BTNA"]     = "FastSmirk";
triggerMap["R_BTNB+L_BTNB"]     = "Anger";
triggerMap["R_BTNC+L_BTNC"]     = "Fear";
triggerMap["R_JOY+L_JOY"]       = "SpeedChange";
triggerMap["R_MODE+L_MODE"]     = "FactoryReset";
